function verifiedRounding(ctx,doc,rows,expected,actual){
  if(!Array.isArray(rows)||rows.length!==1||doc.is_draft!==false||
     String(doc.id)!==String(ctx.easybillDocumentId)||
     String(doc.currency)!==String(ctx.billingCase?.currency)||
     Number(doc.calc_vat_from)!==1) return {};
  const event=rows[0].payload;
  const proof=event?.roundingProof;
  if(event?.worker!=='n8n-easybill-document-v2'||
     String(event.easybillDocumentId)!==String(doc.id)||
     event.documentNumber!==ctx.documentNumber||
     proof?.method!=='GROSS_AGGREGATE_VS_ROUNDED_LINES'||
     proof.lineCount!==doc.items?.length||
     !Number.isFinite(proof.vatPercent)||proof.vatPercent<=0) return {};
  for(const key of ['netCents','vatCents','grossCents']){
    if(proof.sourceAmounts?.[key]!==expected[key]||
       proof.documentAmounts?.[key]!==actual[key]||
       event.verifiedDocumentAmounts?.[key]!==actual[key]) return {};
  }
  if(expected.netCents+expected.vatCents!==expected.grossCents||
     actual.grossCents!==expected.grossCents||
     actual.netCents!==Math.round(actual.grossCents*100/(100+proof.vatPercent))||
     actual.vatCents!==actual.grossCents-actual.netCents) return {};
  return proof;
}
const ctx=$('Prepare Customer Delivery').first().json;
const loaded=$('Easybill Load Customer Document').first().json;
const doc=loaded.body??loaded;
const verificationRows=$json.body??$json;
if(!doc.id||String(doc.number||'')!==ctx.documentNumber)throw new Error('billing_customer_delivery_document_mismatch');
const amountCheckedKinds=new Set(['ORDER_CONFIRMATION_PROFORMA','PROFORMA_UPDATE','INVOICE']);
if(amountCheckedKinds.has(String(ctx.kind||''))){
  const actualGrossCents=Number(doc.amount);
  const actualNetCents=Number(doc.amount_net);
  const actualVatCents=actualGrossCents-actualNetCents;
  const expectedNetCents=Number(ctx.billingCase?.subtotal_net_cents);
  const expectedVatCents=Number(ctx.billingCase?.vat_cents);
  const expectedGrossCents=Number(ctx.billingCase?.total_gross_cents);
  if(!Number.isInteger(actualGrossCents)||!Number.isInteger(actualNetCents)||!Number.isInteger(expectedNetCents)||!Number.isInteger(expectedVatCents)||!Number.isInteger(expectedGrossCents)){
    throw new Error('FATAL_billing_customer_delivery_amounts_missing');
  }
  const proof=verifiedRounding(ctx,doc,verificationRows,
    {netCents:expectedNetCents,vatCents:expectedVatCents,grossCents:expectedGrossCents},
    {netCents:actualNetCents,vatCents:actualVatCents,grossCents:actualGrossCents});
  if((actualNetCents!==expectedNetCents||actualVatCents!==expectedVatCents||actualGrossCents!==expectedGrossCents)&&!proof.method){
    throw new Error('FATAL_billing_customer_delivery_amount_mismatch:'+ctx.documentNumber);
  }
}
const output={...ctx,easybillDocument:doc,emailAlreadySent:Boolean(doc.last_postbox_id)};
return [{json:output}];
